import { readFileSync, readdirSync } from 'fs';
import { join } from 'path';

const root = 'server/content';
const npcContent = readFileSync(join(root, 'scripts/_unpack/225/all.npc'), 'utf-8');
const blocks = npcContent.split(/\n(?=\[)/);
type N = { cfg: string; name: string; vis: number; hp: number; atk: number; str: number; def: number; aggr: boolean; };
const out: N[] = [];
for (const b of blocks) {
  const m = b.match(/^\[([^\]]+)\]/);
  if (!m) continue;
  const get = (k: string) => (b.match(new RegExp('^' + k + '=(.*)$', 'm'))?.[1] ?? '').trim();
  const name = get('name');
  const vis = parseInt(get('vislevel'));
  const hp = parseInt(get('hitpoints'));
  if (!name || isNaN(vis) || isNaN(hp) || hp <= 0) continue;
  out.push({ cfg: m[1], name, vis, hp, atk: parseInt(get('attack')) || 0, str: parseInt(get('strength')) || 0, def: parseInt(get('defence')) || 0, aggr: /aggressive/i.test(get('huntmode')) });
}
const byCfg = new Map(out.map(n => [n.cfg, n]));

// npc.pack id->name
const pack = readFileSync(join(root, 'pack/npc.pack'), 'utf-8');
const idToCfg = new Map<number, string>();
for (const line of pack.split('\n')) {
  const i = line.indexOf('=');
  if (i === -1) continue;
  const id = parseInt(line.slice(0, i));
  if (!isNaN(id)) idToCfg.set(id, line.slice(i + 1).trim());
}

// parse maps
const mapsDir = join(root, 'maps');
const spawns = new Map<string, { x: number; z: number; lvl: number }[]>();
for (const file of readdirSync(mapsDir)) {
  const mm = file.match(/^m(\d+)_(\d+)\.jm2$/);
  if (!mm) continue;
  const mapX = +mm[1], mapZ = +mm[2];
  const c = readFileSync(join(mapsDir, file), 'utf-8');
  const idx = c.indexOf('==== NPC ====');
  if (idx === -1) continue;
  const after = c.slice(idx + 13);
  const nxt = after.indexOf('====');
  const blk = nxt === -1 ? after : after.slice(0, nxt);
  for (const line of blk.split('\n')) {
    const t = line.trim();
    const sm = t.match(/^(\d+)\s+(\d+)\s+(\d+):\s*(\d+)$/);
    if (!sm) continue;
    const cfg = idToCfg.get(+sm[4]);
    if (!cfg) continue;
    const x = mapX * 64 + +sm[2], z = mapZ * 64 + +sm[3];
    if (!spawns.has(cfg)) spawns.set(cfg, []);
    spawns.get(cfg)!.push({ x, z, lvl: +sm[1] });
  }
}

function nearestLumbridge(x: number, z: number) {
  return Math.hypot(x - 3222, z - 3222);
}

const list = [...byCfg.values()];
const cands = list.filter(n => n.vis >= 8 && n.hp <= 60 && n.def <= 12);
for (const n of cands.sort((a, b) => b.vis - a.vis)) {
  const sp = spawns.get(n.cfg) || [];
  // find the nearest spawn to Lumbridge
  let best: { x: number; z: number; lvl: number } | null = null;
  for (const s of sp) if (!best || nearestLumbridge(s.x, s.z) < nearestLumbridge(best.x, best.z)) best = s;
  const loc = best ? `@(${best.x},${best.z})L${best.lvl} dist${nearestLumbridge(best.x, best.z).toFixed(0)} n=${sp.length}` : 'NO SPAWN';
  console.log(`${n.name.padEnd(18)} L${String(n.vis).padEnd(3)} hp${String(n.hp).padEnd(3)} atk${String(n.atk).padEnd(3)} str${String(n.str).padEnd(3)} def${String(n.def).padEnd(3)} ${n.aggr ? 'AGGR' : '    '} ${loc}`);
}

