const end = Date.now() + 90_000;
const startSkills = Object.fromEntries(sdk.getSkills().map(s => [s.name, s.baseLevel]));
let kills = 0, attacks = 0, errors = 0;
let lastStyleSwitch = 0;
let styleIdx = 1; // start Strength
async function setStyle(train: string) {
  const st = sdk.getState()?.combatStyle?.styles.find(o => o.trainsSkills.includes(train));
  if (st) await sdk.sendSetCombatStyle(st.index);
}
await setStyle('Strength');
while (Date.now() < end) {
  const s = sdk.getState();
  if (!s) break;
  const p = s.player;
  if (!p || p.worldX === 0) { await new Promise(r=>setTimeout(r,300)); continue; }
  // eat if low
  if (p.hp <= 3) { const f = sdk.findInventoryItem(/bread|shrimps/i); if (f) { await bot.eatFood(f); } }
  // switch style every 15s
  if (Date.now() - lastStyleSwitch > 15000) {
    lastStyleSwitch = Date.now();
    styleIdx = styleIdx === 1 ? 0 : 1; // alternate Strength/Attack
    await setStyle(styleIdx === 1 ? 'Strength' : 'Attack');
  }
  const npc = sdk.findNearbyNpc(/^(man|woman|rat|goblin)$/i, { reachable: true });
  if (!npc) { await new Promise(r=>setTimeout(r,200)); continue; }
  try {
    attacks++;
    const r = await bot.attack(npc, 4000);
    if (r.success) kills++;
  } catch (e) { errors++; }
}
const endSkills = Object.fromEntries(sdk.getSkills().map(s => [s.name, s.baseLevel]));
const gained: any = {};
for (const k of Object.keys(endSkills)) if (endSkills[k] !== startSkills[k]) gained[k] = `${startSkills[k]}->${endSkills[k]}`;
return { attacks, kills, errors, gained, combat: sdk.getState()?.player?.combatLevel };

